curl -s "https://services.codeninjas.com/api/v1/facility/profile/slug/east-gwillimbury-on-ca" > /tmp/eg-api-response.json && python3 -c "
import json
with open('/tmp/eg-api-response.json') as f:
    d = json.load(f)
# Show top-level keys and types
for k,v in d.items():
    t = type(v).__name__
    if isinstance(v, str) and len(v) > 200:
        t = f'str({len(v)} chars)'
    elif isinstance(v, str):
        t = f'str: \"{v}\"'
    elif isinstance(v, bool):
        t = f'bool: {v}'
    elif isinstance(v, (int,float)):
        t = f'num: {v}'
    elif v is None:
        t = 'null'
    print(f'{k}: {t}')
"

python3 -c "
import json
with open('/tmp/eg-api-response.json') as f:
    d = json.load(f)
# Parse additionalSettings
addl = json.loads(d['additionalSettings'])
# Show structure
def show_keys(obj, prefix='', depth=0):
    if depth > 3: return
    if isinstance(obj, dict):
        for k,v in obj.items():
            if isinstance(v, dict):
                print(f'{prefix}{k}: {{...}}')
                show_keys(v, prefix+'  ', depth+1)
            elif isinstance(v, list):
                print(f'{prefix}{k}: [{len(v)} items]')
                if v and isinstance(v[0], dict):
                    show_keys(v[0], prefix+'  [0].', depth+1)
            elif isinstance(v, str) and len(v) > 100:
                print(f'{prefix}{k}: str({len(v)} chars)')
            elif isinstance(v, str):
                val = v[:80]
                print(f'{prefix}{k}: \"{val}\"')
            elif isinstance(v, bool):
                print(f'{prefix}{k}: {v}')
            else:
                print(f'{prefix}{k}: {v}')
show_keys(addl)
"

