  const scriptDir = dirname(fileURLToPath(import.meta.url));
  const scriptPath = join(scriptDir, "scrape_camps.py");

  try {
    const proc = Bun.spawn(["python3", scriptPath, slug], {
      stdout: "pipe",
      stderr: "pipe",
    });

