      if (VERBOSE) console.log(`  Camp scraper error: ${data.error}`);
      return "";
    }

    if (VERBOSE) console.log(`  Camp scraper found ${data.count} camps`);
    return data.formatted || "";
  } catch (e: any) {
    if (VERBOSE) console.log(`  Camp scraper failed: ${e.message}`);
    return "";
  }
}

